const SKILL_TREE_UF_BOUNDS_10G = {
  'changeling|damageTakenMult': { min:-0.25, max:0.6 },
  'changeling|radius':          { min:-2,    max:2 },
  'diamonddog|damageTakenMult': { min:-0.25, max:0.6 },
  'diamonddog|radius':          { min:-2,    max:2 },
  'gargoyle|damageTakenMult':   { min:-0.35, max:0.5 },
  'gargoyle|radius':            { min:-2,    max:2 },
};

function ST10G(classId, stat, amount, perRank){
  const e = { type:'stat', classId, stat, amount };
  if (perRank != null) e.perRank = perRank;
  return e;
}
function UF10G(classId, field, amount){
  const b = SKILL_TREE_UF_BOUNDS_10G[classId + '|' + field];
  return { type:'uniqueField', classId, field, amount, min:b.min, max:b.max };
}
function FL10G(classId, field, value){ return { type:'uniqueFlag', classId, field, value }; }
function SY10G(classId, stat, perOwned, tag){ return { type:'synergyStat', classId, stat, perOwned, tag }; }

